// One item per section to rebuild. section: hero, header, pricing, features, testimonials, faq, cta or footer
return [
  { json: { url: 'https://linear.app', section: 'hero' } },
  { json: { url: 'https://linear.app/pricing', section: 'pricing' } },
  { json: { url: 'https://stripe.com', section: 'footer' } }
];

// Keep the sections that came back as templates; name each file; list the ones that failed.
const asked = $('List Pages and Sections').all().map(i => i.json)
const ok = [], failed = []
$input.all().forEach((item, i) => {
  const a = asked[i] || {}
  const host = String(a.url).split('/')[2].replace(/^www\./, '')
  if (item.json.code) ok.push({ json: { url: a.url, section: a.section, code: item.json.code, fileName: host + '-' + a.section + '-elementor.json' }, pairedItem: { item: i } })
  else failed.push(a.url + ' ' + a.section + ': ' + (item.json.error?.message || item.json.error || 'no template'))
})
if (!ok.length) throw new Error('None of the sections could be rebuilt. ' + failed.join('; '))
ok[0].json.failed = failed
return ok
